"""Record analytical review separately from every original label and model result."""
import json
from collections import Counter
from pathlib import Path

root=Path(__file__).resolve().parents[2]
out=root/'data/external-review'
report=json.loads((out/'comparison.json').read_text(encoding='utf-8'))
dialogs={x['conversation_id']:x for x in map(json.loads,(root/'data/dev/indexed-transcripts.jsonl').read_text(encoding='utf-8').splitlines())}
previous=json.loads((root/'research/reliability/criterion06-assessments.json').read_text(encoding='utf-8'))
old={r['id']:r for r in previous['cases']}
reviews=[]

def decision(values,reason,ids=(),status='working_preference',authority='assistant analysis against PDF; not official GT'):
    return {'status':status,'acceptable_working_values':values,'reason':reason,'evidence_ids':list(ids),'authority':authority}

custom={}
def add(c,conversation_ids,values,reason,**kwargs):
    for cid in conversation_ids.split(): custom[(cid,c)]=decision(values,reason,**kwargs)

