for row in report['disagreements']:
    cid,c=row['conversation_id'],row['criterion_id']
    d=custom.get((cid,c))
    if d is None and c=='06' and cid in old:
        x=old[cid];d=decision(x['acceptable'],x['reason'],x['evidence_ids'],status='expert_review' if x['classification']=='disputed' else 'working_preference')
    if d is None and c=='07' and row['values'].get('runtime')=='no' and row['values'].get('azimxxd')=='yes':
        d=decision(['no'],'В завершающем фрагменте есть только прощание/благодарность/общая вежливость; нет явного итога или предложения помощи. Чужой промпт принимает одно прощание. Проверить возможный итог в более ранней реплике перед утверждением экспертной метки.',status='working_preference')
    if d is None:
        known={v for v in row['values'].values() if v is not None}
        if len(known)==1 and None in row['values'].values():
            d=decision([], 'Известные ответы совпадают, но другая сторона сохранила неопределённость. Согласие не доказывает, что неизвестное нужно заменить. Для продуктовых правил/ASR требуется источник или эксперт.',status='coverage_difference_not_proven_error')
        else:
            d=decision([], 'Граница зависит от конкретного смысла критерия или недостающего продуктового контекста. Нет независимого эталона для автоматической замены.',status='expert_review')
    messages={m['message_id']:m for m in dialogs[cid]['messages']}
    assert all(mid in messages for mid in d['evidence_ids'])
    reviews.append({**{k:row[k] for k in ('conversation_id','criterion_id','values')},**d,'evidence':[messages[mid] for mid in d['evidence_ids']]})
assert len(reviews)==134
result={'notice':'Analytical triage, not independently labeled Ground Truth; no original labels, production verdicts or prompts changed. Acceptable values are working interpretations, not statistical error bounds.', 'pdf_source':'CQA_Chat_Quality_Checklist 1.pdf, pages 1-3','positions':len(reviews),'status_counts':dict(Counter(x['status'] for x in reviews)),'reviews':reviews}
(out/'adjudication.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'positions':len(reviews),'statuses':result['status_counts']},indent=2))
